 const urg=S.caps.filter(k=>k.urg==='urgente'&&k.st&&k.st!=='res').length;if(urg)h+='<div class="card warnc" onclick="tab=\'cap\';capFilter=\'urg\';render()">🔥 '+urg+' petición'+(urg>1?'es urgentes':' urgente')+' sin resolver ›</div>';
