S.fz=S.fz||{};S.fz.ev=S.fz.ev||{};S.fz.ea=S.fz.ea||{};S.fz.g=S.fz.g||[];S.fz.cfg=Object.assign({tope:1503662.51,uma:117.31,wa:''},S.fz.cfg||{});
const ETP={rec:'🚶 Recorrido casa por casa',merc:'🛒 Domingo de mercadito',reu:'🏠 Reunión vecinal',mit:'📣 Mitin o evento masivo',pri:'🤝 Reunión privada',med:'🎙️ Entrevista o medios',deb:'⚖️ Debate',cie:'🎉 Cierre de campaña',otr:'📌 Otro'};
const GCAT={prop:'Propaganda impresa (volantes, lonas, carteles)',util:'Propaganda utilitaria (gorras, playeras, etc.)',bar:'Bardas',esp:'Espectaculares y vía pública',ev:'Eventos (renta, sonido, templete, sillas)',tra:'Transporte y combustible',ali:'Alimentos y bebidas',dig:'Redes sociales y publicidad digital',med:'Producción de audio, foto y video',per:'Personal y estructura',dd:'Día D (representantes)',ofi:'Oficina y servicios',otr:'Otros'};
