const money=n=>'$'+Number(n||0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
const addD=(iso,n)=>{const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+n);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const lim90=()=>90*(+S.fz.cfg.uma||117.31);
let agSeg='rec',evFil='prox';
function fzAuto(){const L=[];DAYS.forEach(d=>L.push({id:'r'+d.dia,auto:1,tp:'rec',n:'Recorrido casa por casa · '+d.turno,f:d.fecha,hi:d.turno==='Mañana'?'09:00':'16:30',hf:d.turno==='Mañana'?'13:00':'20:00',lug:'Secciones '+d.secs.map(pad).join(', ')+' · '+esc((SB[d.secs[0]].col||'').split(',').slice(0,2).join(',')),sec:d.secs[0],pub:1,on:0,est:'prog'}));
 MERC.forEach(m=>L.push({id:'m'+m.fecha,auto:1,tp:'merc',n:'Domingo de mercadito',f:m.fecha,hi:'09:00',hf:'13:00',lug:m.cols.slice(0,2).join(', '),sec:m.secs[0],pub:1,on:0,est:'prog'}));return L}
function fzEvents(){return fzAuto().map(e=>Object.assign(e,S.fz.ea[e.id]||{})).concat(Object.values(S.fz.ev)).filter(e=>!e.del).sort((a,b)=>(a.f+a.hi).localeCompare(b.f+b.hi))}
function evGet(id){return fzEvents().find(e=>e.id===id)}
function evSet(e){const keep=Object.assign({},e);if(e.auto){const o={};['n','f','hi','hf','lug','sec','pub','on','resp','asis','est','sif','sifF','cr','ph','nt','tp'].forEach(k=>{if(e[k]!==undefined)o[k]=e[k]});S.fz.ea[e.id]=o}else S.fz.ev[e.id]=keep;save(true)}
function evSt(e){const t=todayIso(),due=addD(e.f,-7);if(e.est==='cancel')return e.cr?['Cancelación reportada','#5f6368']:(t>addD(e.f,2)?['Cancelación vencida','#b3261e']:['Reportar cancelación','#b58900']);
 if(e.sif)return ['Registrado en SIF','#1a9d2b'];if(t>due)return ['Registro tardío','#b3261e'];if(daysTo(due)<=7)return ['Registrar antes del '+fdate(due,{day:'numeric',month:'short'}),'#b58900'];return ['Registrar antes del '+fdate(due,{day:'numeric',month:'short'}),'#5f6368']}
function gReq(g){const m=[];if(g.pl)return m;if(g.pago==='ef'&&+g.m>lim90())m.push(['r','Pago en efectivo mayor a 90 UMA ('+money(lim90())+'): debe ser transferencia o cheque nominativo']);
 if(!g.sif)m.push([todayIso()>addD(g.f,3)?'r':'a','Registrar en SIF a más tardar el '+fdate(addD(g.f,3),{day:'numeric',month:'short'})]);
 if(g.pago==='esp'){if(!g.ctr)m.push(['a','Falta contrato y recibo de la aportación en especie']);if(!g.ap)m.push(['a','Falta nombre del aportante'])}else{if(!g.fac)m.push(['a','Falta factura (CFDI PDF y XML)']);if(g.fac&&g.uuid&&!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(g.uuid.trim()))m.push(['a','El folio fiscal (UUID) no tiene el formato correcto'])}
 if(!g.evi)m.push(['a','Falta evidencia (foto o muestra)']);if(g.cat==='bar'&&!g.per)m.push(['a','Falta permiso por escrito del dueño de la barda']);if(g.cat==='per'&&!g.ctr)m.push(['a','Falta contrato de prestación de servicios']);
 if(g.rfc&&!/^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/i.test(g.rfc.trim()))m.push(['a','El RFC del proveedor no tiene el formato correcto']);return m}
function fzSpent(){let s=0,p=0;S.fz.g.forEach(g=>{if(g.pl)p+=+g.m||0;else s+=+g.m||0});return {s,p}}
function fzAlerts(){const t=todayIso(),A=[],E=fzEvents();
 const late=E.filter(e=>e.est!=='cancel'&&!e.sif&&t>addD(e.f,-7)&&e.f>=t);if(late.length)A.push({l:'r',t:late.length+' evento'+(late.length>1?'s':'')+' próximos con registro de agenda vencido (7 días antes)',go:'ev:sif'});
 const wk=E.filter(e=>e.est!=='cancel'&&!e.sif&&t<=addD(e.f,-7)&&daysTo(addD(e.f,-7))<=7);if(wk.length)A.push({l:'a',t:wk.length+' evento'+(wk.length>1?'s':'')+' por registrar esta semana',go:'ev:sif'});
 const canc=E.filter(e=>e.est==='cancel'&&!e.cr);if(canc.length)A.push({l:canc.some(e=>t>addD(e.f,2))?'r':'a',t:canc.length+' cancelación'+(canc.length>1?'es':'')+' por reportar (48 h después de la fecha)',go:'ev:canc'});
 const past=E.filter(e=>e.f<t&&e.est==='prog');if(past.length&&t>=DAYS[0].fecha)A.push({l:'a',t:past.length+' evento'+(past.length>1?'s':'')+' pasados sin confirmar si se realizaron',go:'ev:past'});
 const noev=E.filter(e=>e.est==='hecho'&&!e.ph);if(noev.length)A.push({l:'a',t:noev.length+' evento'+(noev.length>1?'s':'')+' realizados sin fotos de evidencia',go:'ev:past'});
 const G=S.fz.g.filter(g=>!g.pl);const gl=G.filter(g=>!g.sif&&t>addD(g.f,3));if(gl.length)A.push({l:'r',t:gl.length+' gasto'+(gl.length>1?'s':'')+' sin registrar en SIF después de 3 días',go:'g'});
 const ef=G.filter(g=>g.pago==='ef'&&+g.m>lim90());if(ef.length)A.push({l:'r',t:ef.length+(ef.length>1?' pagos en efectivo mayores':' pago en efectivo mayor')+' a 90 UMA',go:'g'});
 const doc=G.filter(g=>gReq(g).some(r=>r[0]==='a'&&!/SIF/.test(r[1])));if(doc.length)A.push({l:'a',t:doc.length+' gasto'+(doc.length>1?'s':'')+' con documentación incompleta',go:'g'});
 const sp=fzSpent(),T=+S.fz.cfg.tope||0;if(T){const k=sp.s/T,kp=(sp.s+sp.p)/T;if(k>=1)A.push({l:'r',t:'Rebase del tope de gastos: '+Math.round(100*k)+'% ('+money(sp.s)+' de '+money(T)+')',go:'g'});else if(k>=.8)A.push({l:k>=.9?'r':'a',t:'Llevas '+Math.round(100*k)+'% del tope de gastos',go:'g'});else if(kp>=.9)A.push({l:'a',t:'Con lo presupuestado llegarías al '+Math.round(100*kp)+'% del tope',go:'g'})}
 return A}
function alertBox(A){if(!A.length)return '<div class="card" style="border-color:var(--ok)"><b style="color:var(--ok)">✔ Todo en regla con fiscalización</b></div>';return '<div class="card" style="border-color:'+(A.some(a=>a.l==='r')?'#b3261e':'#b58900')+'"><b>Cumplimiento INE</b>'+A.map(a=>'<div class="fzal" data-go="'+a.go+'" style="margin:6px 0;cursor:pointer;color:'+(a.l==='r'?'#b3261e':'inherit')+'">'+(a.l==='r'?'🔴 ':'🟠 ')+esc(a.t)+' ›</div>').join('')+'</div>'}
