  h+='<div class="chips">'+[['prox','Próximos'],['sif','Por registrar'],['past','Pasados'],['canc','Cancelados'],['all','Todos']].map(a=>'<button data-ef="'+a[0]+'" class="'+(evFil===a[0]?'on':'')+'">'+a[1]+'</button>').join('')+'</div><button class="btn" id="evadd">＋ Nuevo evento</button>';
  const L=E.filter(e=>evFil==='all'||(evFil==='prox'&&e.f>=t&&e.est!=='cancel')||(evFil==='sif'&&!e.sif&&e.est!=='cancel'&&e.f>=t)||(evFil==='past'&&e.f<t&&e.est!=='cancel')||(evFil==='canc'&&e.est==='cancel'));
